    minorHumanEdits: { no: 'Opptak med små manuelle endringer', ai: 'opptak' },
    humanEdits: { no: 'Redigert av et menneske', ai: 'redigert' },
    compositeCapture: { no: 'Satt sammen av flere opptak', ai: 'redigert' },
