    const { w, h, g } = G; const ix = new Float32Array(w * h), iy = new Float32Array(w * h);
    for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) { const i = y * w + x; ix[i] = (g[i + 1] - g[i - 1]) / 2; iy[i] = (g[i + w] - g[i - w]) / 2; }
