      fields.forEach(function (f, fi) {
        var hit = -1;
        if (header && f.guess) heads.forEach(function (h, i) { if (hit < 0 && f.guess.test(h) && Object.keys(map).every(function (k) { return map[k] !== i; })) hit = i; });
        if (hit < 0 && !header) hit = fi < heads.length ? fi : -1;
        map[f.key] = hit;
