  --faktisk-blue: #0050FC;
  --faktisk-blue-hover: #0040D9;
  --bg-page: #9D9D9D;
  --bg-topbar: #707070;
  --bg-placeholder: #7B7B7B;
  --bg-letterbox: #878787;
  --bg-input: #D9D9D9;
  --text-on-blue: #FFFFFF;
