      for (let y = 0; y < h; y++) {
        const yi = y - s0.dy; if (yi < 0 || yi >= r.h) continue;
        for (let x = 0; x < w; x++) {
          const xi = x - s0.dx; if (xi < 0 || xi >= r.w) continue;
          const j = yi * r.w + xi; if (!r.valid[j]) continue;
