    let s = 0, n = 0;
    for (let y = by; y < by + bh; y += step) {
      const y2 = y + dy; if (y < 0 || y >= A.h || y2 < 0 || y2 >= B.h) continue;
      for (let x = bx; x < bx + bw; x += step) {
        const x2 = x + dx; if (x < 0 || x >= A.w || x2 < 0 || x2 >= B.w) continue;
        s += Math.abs(A.g[y * A.w + x] - B.g[y2 * B.w + x2]); n++;
